'use strict';
// Documents 00 and 02-13.
const H = require('./helpers.js');
const { CO, CO_UP, FORMED, DEFILE, EIN, RA, ADDR, TALENT_DATE, AUTH_UNITS, RESERVE, FOUNDERS, BROCK, CLASS_A, CLASS_B, OUTSTANDING, A_TOTAL_PRICE, FMV_TOTAL, THRESHOLD, CEO, CTO, JGN_MEMBERS, N_FOUNDERS, RUPIA_FIRST, BROCK_DOC, RECEIPT_FIRST, RECEIPT_LAST, money, num, fdPct, outPct, votePct, vested, monthly, price, nbName, heDoc, FOUNDERS_AND, JGN_AND, doc, EFF, DEF_ONLY, DEFINED, kv, tbl, coSig, personSig, memberSigs, capRows } = H;

const CAP_HEAD = ['Member', 'Class and office', 'Units', 'Fully diluted %', 'Per-Unit price', 'Total purchase price', 'Immediately vested', 'Restricted over 48 months'];
function capTable() {
  const rows = FOUNDERS.map(f => [nbName(f), 'Class A; ' + f.office, num(f.units), fdPct(f.units), '$0.001', price(f), num(vested(f)), num(vested(f))]);
  rows.push([nbName(BROCK), 'Class B; Co-Founder', num(BROCK.units), fdPct(BROCK.units), 'None (profits interest)', 'None', 'Per Talent Agreement Section 5.4', 'Per Talent Agreement Section 5.4']);
  rows.push(['Reserved Units', 'Unissued (Operating Agreement Section 3.13)', num(RESERVE), fdPct(RESERVE), '', '', '', '']);
  rows.push(['<strong>Total authorized</strong>', '', '<strong>' + num(AUTH_UNITS) + '</strong>', '<strong>100%</strong>', '', '<strong>' + money(A_TOTAL_PRICE) + '</strong>', '<strong>' + num(CLASS_A / 2) + '</strong>', '<strong>' + num(CLASS_A / 2) + '</strong>']);
  return tbl(CAP_HEAD, rows, 'cap', H.CAP_COLS);
}
const PAID_BY = 'Cash payment into the Company bank account (Operating Agreement Section 3.5)';
const OWN_SUMMARY = `${FOUNDERS.map(f => fdPct(f.units)).join(' / ')} / ${fdPct(BROCK.units)} across six Members on a fully diluted basis, with ${fdPct(RESERVE)} reserved and unissued`;

// 00 Master Record Book Index
function doc00() {
  const body = EFF +
  `<p>This record book documents the five Founders' purchase of restricted Class A Units at a total company equity Fair Market Value of ${money(FMV_TOTAL)} and a Fair Market Value of $0.001 per Class A Unit, paid in cash into the Company's bank account as each Founder's initial Capital Contribution; the issuance of ${num(CLASS_B)} Class B Units to Brock Smith as profits interests under the Talent Agreement, without his signature; and the reservation of ${num(RESERVE)} unissued Units for future strategic partners. It also records the agreed ownership, governance, vesting, IP ownership, the JGN arrangements (Brand License, promotion through the Social Accounts, Platform contribution and JGN Funding Advances), transfer restrictions, restrictive covenants, the historical operating expenses and the accounting separation of the Founder purchase.</p>
  <h2>1. CAPITALIZATION AND PURCHASE TERMS</h2>` + capTable() +
  kv([['Authorized Units', num(AUTH_UNITS)], ['Issued Class A Units', num(CLASS_A)], ['Issued Class B Units', num(CLASS_B)], ['Outstanding Units', num(OUTSTANDING)], ['Reserved Units (unissued)', num(RESERVE)], ['Fully diluted ownership', '100%'],
    ['Total company equity FMV', money(FMV_TOTAL)], ['FMV per Class A Unit', '$0.001'], ['Class B Threshold Amount', money(THRESHOLD)], ['Aggregate Founder purchase price', money(A_TOTAL_PRICE)], ['Aggregate Founder Capital Contributions', money(A_TOTAL_PRICE)], ['Aggregate capital credited to Members\' Capital Accounts', money(A_TOTAL_PRICE)],
    ['Interest type', 'Class A: restricted Common Units constituting capital interests. Class B: non-voting Common Units constituting profits interests.'], ['Vesting', 'Class A: 50% immediately vested; 50% monthly over 48 months. Class B: per Talent Agreement Section 5.4.'], ['Transfer Date', 'Actual Closing Date']]) +
  `<h2>2. COMPANY IDENTIFIERS OF RECORD</h2>` +
  kv([['Legal name', CO], ['Jurisdiction', 'Delaware limited liability company'], ['Date of formation', FORMED], ['Delaware file number', DEFILE], ['Federal employer identification number (EIN)', EIN], ['Registered agent', RA], ['Principal business office', ADDR], ['Company bank accounts', 'Business checking account in the Company\'s legal name, opened under the Banking Resolution before the Actual Closing Date and recorded in the Company Account Schedule']]) +
  `<h2>3. DOCUMENTS INCLUDED IN THIS RECORD BOOK</h2>` +
  tbl(['No.', 'Document', 'Purpose'], [
    ['00', 'Master Record Book Index', 'Record-book index and closing record.'],
    ['01', 'Operating Agreement', 'Primary Company governance, ownership, voting, transfer, vesting, capital-account, Class B, Reserved Unit, IP/account, JGN and approval-threshold instrument.'],
    ['02', 'Initial Member and Organizational Written Consent', 'Approves FMV, initial Capital Contributions, purchase price, equity issuance, the Class B issuance, payment process, updated records and supporting documents.'],
    ['03', 'Founder Equity Fair Market Value Determination Memorandum', 'Good-faith FMV support for the Founder purchase price, per-Unit value and Class B Threshold Amount, including completed factual worksheet and launch-stage valuation rationale.'],
    ['04', 'Founder Purchase Price Payment Instructions', 'How each Founder\'s purchase price is paid in cash into the Company bank account; no notes, credits or deferred-payment rights are authorized.'],
    ['05', 'Aggregate Founder Purchase Closing Statement', 'Reconciles all Units, prices, payments and issuance conditions.'],
    ['06', 'Founder Payment and Capital Contribution Ledger', 'Records each payment, Capital Contribution treatment and accounting fields.'],
    ['07', 'Company Officer Certificate – Founder Equity Closing', 'Officer certification of payments, issuance and record updates.'],
    ['08', 'Officer Appointment Record and Authority Certificate', 'Officer titles, lanes and spending authority as delegated under the Operating Agreement.'],
    ['09', 'Banking Resolution', 'Opening of the Company bank account, authorized signers and account controls.'],
    ['10', 'Official Unit Ledger', 'Register of issued Units by Member and class, with entry numbers, and of the Reserved Units.'],
    ['11', 'Capitalization Table', 'Outstanding and fully diluted ownership by Member, Units, percentages and purchase price.'],
    ['12', 'Founder Equity and Vesting Ledger', 'Vested and restricted Units, vesting schedule and repurchase terms for each Founder; Class B vesting reference.'],
    ['13', 'Founder Contribution and Separation Schedule', 'Per-Member record separating purchase price, Capital Contributions, JGN Funding Advances, IP and services.'],
    ['14', 'Historical Company Operating Expense and JGN Funding Advance Schedule', 'Record of historical operating expenses by category, who paid, and accounting treatment, with the JGN Funding Ledger as the controlling amount record.'],
    ['15', 'Company Asset Schedule', 'Categories of Company-owned software, data, account and record assets, and of the JGN-owned Brand and Social Accounts.'],
    ['16', 'IP Assignment Schedule and Chain of Title Register', 'Chain of title for each category of Company IP and the documents that establish it.'],
    ['17', 'Company Account Schedule', 'Company-critical account categories and control standard.'],
    ['18', 'Founder Proprietary Information, IP Assignment and Data Security Agreement (Founder PIIA)', 'Founder confidentiality, invention assignment, data-security and account-control obligations.'],
    ['19', 'JGN Media LLC Platform Contribution, Brand License, Funding and Account Transition Agreement (JGN Agreement)', 'Entity-level assignment of Platform-specific assets from JGN, the Brand License, the promotion covenant, JGN Funding Advances and their repayment terms, revenue allocation and account transition.'],
    ['20', 'JGN Member Consent Approving Nosebleed Agreement', 'JGN member approval of the JGN Agreement and authority for its signatory.'],
    ['21', 'Closing Checklist and Signature Index', 'Execution sequence and signatory matrix.'],
    ['22', 'Organization and Governance Summary', 'Record-book summary of member-managed structure, officer lanes and the JGN relationship.'],
    ['23', 'Capitalization Reconciliation Report', 'Reconciliation of Units, percentages, FMV, purchase price, Capital Contributions, Capital Accounts, Original Cost, Class B Units, Reserved Units and vesting.'],
    ['24', 'Record Book Certification', 'Company certification of what this record book contains on capitalization, chain of title, records, JGN authority and expenses.'],
    [`${RUPIA_FIRST}–${RUPIA_FIRST + N_FOUNDERS - 1}`, 'Founder Restricted Unit Purchase and Issuance Agreements', 'Individual Founder purchase, vesting, tax-responsibility, securities and continuing-obligation documents.'],
    [String(BROCK_DOC), 'Brock Smith Class B Unit Issuance Record', 'Company record of the Class B issuance to Brock Smith under the Talent Agreement; signed by the Company only.'],
    [`${RECEIPT_FIRST}–${RECEIPT_LAST}`, 'Founder Purchase Price Receipts', 'Receipts completed once each Founder\'s payment is recorded.'],
  ]) +
  `<h2>4. CLOSING RECORD</h2>` +
  kv([
    ['Ownership', OWN_SUMMARY + '.'],
    ['Voting thresholds', 'Every Member approval requires affirmative written votes of Members holding at least 75% of outstanding Class A Units (Section 5.2). Class B Units and Reserved Units do not vote. Where the Operating Agreement measures a vote by Disinterested Ownership, the 75% threshold is measured against the Disinterested Ownership and at least three disinterested Members must vote in favor, subject to Section 5.2 where fewer than three Members are disinterested. Non-response never counts as approval.'],
    ['Units', `${num(AUTH_UNITS)} authorized; ${num(CLASS_A)} Class A Units and ${num(CLASS_B)} Class B Units issued after the Founder closing (${num(OUTSTANDING)} outstanding); ${num(RESERVE)} Reserved Units unissued.`],
    ['Total equity FMV', `${money(FMV_TOTAL)}, for Founder issuance records, subject to reconsideration before the Units are issued if undisclosed Valuation Date facts exist.`],
    ['Per-Unit FMV', '$0.001 per Class A Unit.'],
    ['Aggregate purchase price', money(A_TOTAL_PRICE) + '.'],
    ['Aggregate initial Capital Contributions', money(A_TOTAL_PRICE) + '.'],
    ['Capital Account credit', `${money(A_TOTAL_PRICE)} in aggregate, equal to the aggregate purchase price and aggregate Capital Contributions. The Class B Member's opening Capital Account is zero.`],
    ['Founder purchase math', 'Each Founder\'s purchase price equals Class A Units multiplied by $0.001.'],
    ['Vesting', 'Class A: 50% immediately vested and 50% monthly over 48 months for each Founder. Class B: vests and is forfeitable as Talent Agreement Section 5.4 provides.'],
    ['Restricted capital interests', 'The Class A Units are restricted Common Units constituting capital interests, not profits interests, options, phantom equity or synthetic equity. The Class B Units are profits interests with a Threshold Amount of ' + money(THRESHOLD) + '.'],
    ['Payment', `Each Founder's purchase price is paid in cash into the Company bank account: ${FOUNDERS.map(f => nbName(f) + ' ' + price(f)).join('; ')}; ${money(A_TOTAL_PRICE)} in total. No credit, note or deferred payment is permitted.`],
    ['Purchase price separation', 'Purchase prices are separate from Founder duties, IP assignments, pre-closing services, JGN Funding Advances, other Company expenses and reimbursable expenses.'],
    ['Class B issuance', `${num(CLASS_B)} Class B Units are issued to Brock Smith on the Actual Closing Date as the Initial Units under Section 5.1 of the Talent Agreement (exceeding the 50,000 required there), as profits interests, without a purchase price and without his signature (Operating Agreement Section 3.7). Milestone Units under the Talent Agreement, if earned, are issued from the Reserved Units.`],
    ['Reserved Units', `${num(RESERVE)} authorized Units (${fdPct(RESERVE)} fully diluted) are reserved for future strategic partners and issuable only as a Major Decision (Operating Agreement Section 3.13).`],
    ['Transfer Date', 'The Transfer Date is the Actual Closing Date (Operating Agreement Section 2.8).'],
    ['IP chain of title', 'Founder PIIA, JGN Agreement, JGN Member Consent, Talent Agreement, Company Account Schedule and IP Assignment Schedule and Chain of Title Register are included in or referenced by this record book.'],
    ['Brand and Social Accounts', 'The Nosebleed Sports brand and the Social Accounts are owned by JGN. The Company uses the brand under the exclusive, perpetual, royalty-free, transferable Brand License in the JGN Agreement and is promoted through the Social Accounts under the promotion covenant there.'],
    ['Commercial status', 'The FMV memorandum records the Company as launch-stage: the Platform was built with JGN funding, the Company has no bank account as of the date the memorandum was prepared, no revenue has been received in the Company\'s name, and the Company has no outside financing and no bona fide third-party equity or acquisition offers as of the Valuation Date.'],
    ['Historical expenses and JGN funding', 'Operating Agreement Schedule C, the Founder Contribution and Separation Schedule and the Historical Company Operating Expense and JGN Funding Advance Schedule record that every historical operating expense was funded by JGN as a JGN Funding Advance, repayable by the Company only as the JGN Agreement provides and never by any Member. None of them is purchase price, a Capital Contribution or Unit consideration.'],
    ['JGN authorized signer', `The JGN Agreement signature block identifies ${CEO.name} as Authorized Representative of JGN Media LLC and ${CTO.name}, Chief Technology Officer, as the Company's signer; in the JGN Member Consent all four members of JGN, holding 100% of its membership interests, approve the JGN Agreement.`],
    ['Entity', 'Member-managed Delaware limited liability company.'],
  ]) + coSig('Certified by the Company at closing');
  return doc(0, 'MASTER RECORD BOOK INDEX', body);
}

// 02 Initial Member and Organizational Written Consent
function doc02() {
  const body = `<p><strong>Effective date:</strong> the Unit issuances authorized by this consent occur only on the Actual Closing Date, after all required signatures are delivered and each Founder's purchase price payment is recorded, as stated in Resolution 3. Under Section 2.8 of the Operating Agreement, the Actual Closing Date, the Transfer Date, the Valuation Date and the vesting commencement date are the same date unless the Operating Agreement is amended under Article 16 to provide otherwise. ${DEFINED}</p>
<p>The undersigned, constituting all initial Class A Members of ${CO}, adopt the following resolutions by unanimous written consent, effective upon signature by all Class A Members.</p>
<h2>RECITALS</h2>
<p>A. The Company was formed as a Delaware limited liability company on ${FORMED} (Delaware file number ${DEFILE}) by ${CEO.name} as authorized person, and was assigned EIN ${EIN} on August 17, 2026.</p>
<p>B. The Members desire to complete the Company's Founder closing, documented in this record book, through a purchase of restricted Class A Units at current Fair Market Value, paid in cash, and the issuance of Class B Units to Brock Smith in performance of the Talent Agreement.</p>
<p>C. The Founder closing occurs on the Actual Closing Date, when all required signatures are delivered and all Founder purchase price payments are recorded; that date is the Transfer Date.</p>
<p>D. Before this consent, the Company had no written limited liability company agreement. The only agreement promising an interest in the Company is the Talent Agreement dated as of ${TALENT_DATE} among JGN Media LLC, the Company and Brock Smith, which Section 3.7 of the Operating Agreement performs.</p>
<h2>RESOLUTIONS</h2>
<p>1. Adoption of Operating Agreement. The Limited Liability Company Agreement of the Company, in the form included in this record book as Document 01, is approved and adopted effective as of the Actual Closing Date. By this consent, the Company is bound by the Sections of the Operating Agreement listed in its Section 2.8, and by Section 2 of each Restricted Unit Purchase and Issuance Agreement, from the date each Founder signs, whether or not the Company's signature block has then been signed. The adoption satisfies Section 5.6 of the Talent Agreement.</p>
<p>2. FMV Determination. The Members approve a total company equity Fair Market Value of ${money(FMV_TOTAL)}, a Fair Market Value per Class A Unit of $0.001 and a Class B Threshold Amount of ${money(THRESHOLD)} as of the Transfer Date, supported by the Founder Equity Fair Market Value Determination Memorandum.</p>
<p>3. Issuance of Units. The Company is authorized to issue ${num(CLASS_A)} Class A Units to the Founders in the amounts and percentages shown below, conditioned on execution of required documents and the recording of each Founder's purchase price payment, and ${num(CLASS_B)} Class B Units to Brock Smith on the Actual Closing Date under Section 3.7 of the Operating Agreement, without a purchase price and without his signature. ${num(RESERVE)} authorized Units remain unissued as Reserved Units.</p>
<p>4. Founder Purchases and Capital Contributions. Each Founder makes an initial Capital Contribution to the Company, by cash payment under Section 3.5 of the Operating Agreement, equal to that Founder's purchase price, and thereby acquires the Founder's entire Class A Unit allocation through that Capital Contribution. The aggregate Founder purchase price and aggregate initial Capital Contributions equal ${money(A_TOTAL_PRICE)}.</p>
<p>5. Payment. Each Founder's purchase price is paid in cash into the Company's bank account opened under the Banking Resolution, as Section 3.5 of the Operating Agreement provides. No Founder pays by note, credit or deferred payment. Once the Actual Closing Date occurs, a recorded payment may not be reduced, refunded, offset or recharacterized; if the Actual Closing Date has not occurred within 120 days after the first Founder signs the Operating Agreement, as its Section 3.6 provides, the payments lapse, no Units are issued and each payment is refunded without interest.</p>
<p>6. Capital Account Treatment. Founder purchase price payments shall be recorded as Capital Contributions in exchange for the initial Class A Units and credited to the Members' Capital Accounts in the aggregate amount of ${money(A_TOTAL_PRICE)}. The Class B Member's opening Capital Account is zero.</p>
<p>7. Separate Founder Obligations. IP assignments, confidentiality, data-security, service, vesting, restrictive-covenant and acquisition-cooperation obligations are approved and remain separate from the purchase price and Capital Contributions. Services performed for the Platform before the Actual Closing Date are not consideration for Units.</p>
<p>8. Restricted Unit Agreements and Class B Record. The Members approve the founder-specific Restricted Unit Purchase and Issuance Agreements and the Brock Smith Class B Unit Issuance Record and authorize the Company to execute them.</p>
<p>9. Payment Confirmation Process. The officers are authorized to confirm each Founder's payment against the Company's bank records as Section 3.5 of the Operating Agreement provides (the Chief Technology Officer for each payment, the Chief Executive Officer for the Chief Technology Officer's own), record each payment, issue receipts, and update the Company's books, the Founder Payment and Capital Contribution Ledger, the Members' Capital Accounts, the Official Unit Ledger, the Capitalization Table, the Founder Equity and Vesting Ledger and the Company's tax records.</p>
<p>10. Founder PIIA and JGN Documents. The Members approve the Founder Proprietary Information, IP Assignment and Data Security Agreement (the Founder PIIA), the JGN Media LLC Platform Contribution, Brand License, Funding and Account Transition Agreement (the JGN Agreement) and the JGN Member Consent Approving Nosebleed Agreement, approve the JGN Agreement as a Major Decision under Schedule B of the Operating Agreement after the disclosure in Schedule D, authorize ${CTO.name}, Chief Technology Officer, to execute the JGN Agreement on behalf of the Company, and authorize execution and record-book retention of those documents.</p>
<p>11. Officers and Banking. The Members approve the Officer Appointment Record and Authority Certificate and the Banking Resolution, provided they do not expand authority beyond the Operating Agreement. The officer appointments and banking authority they record are effective upon signature of this consent, so that the Authorized Banking Officers may open the Company bank account and the officers may confirm and record payments before the Actual Closing Date, and continue in effect under the Operating Agreement on and after the Actual Closing Date.</p>
<p>12. Record-Book Documents. The Members approve the following record-book documents as Company records: Master Record Book Index, Company Officer Certificate – Founder Equity Closing, Founder Equity Fair Market Value Determination Memorandum, Founder Purchase Price Payment Instructions, Aggregate Founder Purchase Closing Statement, Founder Payment and Capital Contribution Ledger, Founder Purchase Price Receipts, Official Unit Ledger, Capitalization Table, Founder Equity and Vesting Ledger, Founder Contribution and Separation Schedule, Historical Company Operating Expense and JGN Funding Advance Schedule, Company Asset Schedule, IP Assignment Schedule and Chain of Title Register, Company Account Schedule, Closing Checklist and Signature Index, Organization and Governance Summary, Capitalization Reconciliation Report and Record Book Certification.</p>
<p>13. Omnibus Authority. Each officer is authorized to take lawful actions and sign documents reasonably necessary to implement these resolutions, maintain Company records and preserve acquisition-readiness documentation, subject to the Operating Agreement.</p>` +
  capTable() + `<h2>MEMBER SIGNATURES</h2>` + memberSigs(() => 'Class A Member');
  return doc(2, 'INITIAL MEMBER AND ORGANIZATIONAL WRITTEN CONSENT', body);
}

// 03 FMV Memorandum
function doc03() {
  const body = `<p><strong>Effective date:</strong> this memorandum speaks as of the Valuation Date and is dated as of the Actual Closing Date. The Members approve it before any Units are issued and reconsider it before closing if any undisclosed Valuation Date fact exists. Under Section 2.8 of the Operating Agreement, the Actual Closing Date, the Transfer Date, the Valuation Date and the vesting commencement date are the same date unless the Operating Agreement is amended under Article 16 to provide otherwise. ${DEFINED}</p>` +
  kv([['Company', CO], ['Entity type', 'Delaware limited liability company'], ['Valuation Date', 'Actual Closing Date (the "Valuation Date")'], ['Purpose', `Support the initial Founder purchase and issuance of ${num(CLASS_A)} Class A Units at $0.001 per Unit and the Threshold Amount of the ${num(CLASS_B)} Class B Units.`], ['Total company equity FMV', money(FMV_TOTAL)], ['FMV per Class A Unit', '$0.001'], ['Class B Threshold Amount', money(THRESHOLD)], ['Interest type', 'Class A: restricted Common Units constituting capital interests. Class B: profits interests.'], ['Not an appraisal', 'This memorandum is not an independent appraisal, certified valuation, fairness opinion, formal tax opinion or approval by a tax authority.']]) +
  `<h2>1. VALUATION STANDARD AND SCOPE</h2>
<p>The Members determined in good faith that the total equity Fair Market Value of the Company as of the Valuation Date is ${money(FMV_TOTAL)}. This determination is intended to reflect the Company's actual facts as of the Transfer Date, not gross enterprise value, future projections, aspirational value, replacement cost, the value of the Nosebleed Sports brand or media audience (which the Company does not own), possible strategic value, or later financing or acquisition value.</p>
<p>Future financing, revenue, product development, commercial success, subscriber traction, third-party offers or acquisition value does not retroactively change the good-faith FMV as of the Valuation Date.</p>
<h2>2. FACTUAL VALUATION WORKSHEET</h2>` +
  tbl(['Valuation factor', 'Company factual input', 'Valuation relevance'], [
    ['Cash and cash equivalents', 'None as of the date this memorandum was prepared: the Company had no bank account. The Company bank account is opened under the Banking Resolution before the Actual Closing Date, and the only cash in it on the Valuation Date is the Founders\' purchase price payments of ' + money(A_TOTAL_PRICE) + ' in total. Every Company expense to date has been paid by JGN outside any Company account.', 'Cash directly affects equity value.'],
    ['Accounts receivable', 'None in the Company\'s name. Any subscription, event or sponsorship receipts relating to the Platform before the Valuation Date were collected through accounts held by JGN, as Section 4.4 of the Talent Agreement contemplates, and are allocated under the JGN Agreement.', 'Collectible receivables may increase equity value.'],
    ['Tangible assets', 'None of material value as of the Valuation Date. The Company\'s business is software-, content- and community-based.', 'Physical assets may support value if owned by the Company.'],
    ['Identifiable Company-owned IP', 'The Platform (the Nosebleed Sports application, the website, the Discord community and the Premium Offering) and related Platform-specific code, repositories, data pipelines, documentation and development materials were built with JGN funding by the Founders and are assigned to the Company on the Actual Closing Date through the Founder PIIA and the JGN Agreement, and documented in the IP Assignment Schedule and Chain of Title Register and the Company Account Schedule. The Company does not own the Nosebleed Sports brand or the Social Accounts; it uses the brand under the Brand License. The Platform was in launch stage, had produced no revenue in the Company\'s name and had not been independently valued.', 'Company-owned IP supports value only to the extent ownership and chain of title are documented; a licensed brand and a borrowed audience support value less than owned ones.'],
    ['Software development status', 'Launch stage. The application, the website and the Discord community were built and were being completed for launch by the Chief Technology Officer, after initial development by the Chief Executive Officer and refinement of the website by the Chief Information Officer. The application relied on prototype and non-production data sources and remained subject to final testing, licensed-data-provider selection, app-store distribution, security, deployment, onboarding and commercialization work. The Platform had not established sustained commercial operating history or verified subscriber demand at scale.', 'Stage of development affects risk-adjusted value.'],
    ['Liabilities and accrued obligations', 'Every historical Company operating expense through the Valuation Date was funded by JGN as a JGN Funding Advance, recorded by category in the Historical Company Operating Expense and JGN Funding Advance Schedule and by amount in the JGN Funding Ledger. JGN Funding Advances are a Company obligation repayable without interest only after the Self-Sufficiency Date or at a Change of Control, as the JGN Agreement provides, and reduce equity value accordingly. The Company owes the Monthly Fee, bonuses and revenue shares under the Talent Agreement to the extent allocated to it, funded by JGN until the Self-Sufficiency Date.', 'Liabilities, accrued obligations and approved repayment obligations reduce equity value to the extent outstanding and properly booked.'],
    ['Operating history', 'Limited organizational and development-stage history: formation on ' + FORMED + ', EIN assignment on August 17, 2026, the Talent Agreement effective ' + TALENT_DATE + ', and Platform development through the Valuation Date. The Company had not established sustained commercial operations as of the Valuation Date.', 'Short or limited operating history generally increases risk.'],
    ['Revenue status', 'No revenue received in the Company\'s name as of the Valuation Date. Picks, content and community activity under the Brand before the Valuation Date generated receipts, if any, through JGN-held accounts; the Company\'s own subscription operations begin on the Platform, and ongoing operating expenses substantially exceed any such receipts. The Company is pre-profit and cash-flow negative, dependent on JGN funding.', 'Current recurring revenue may support value; the absence of revenue in the Company\'s name does not establish product-market fit.'],
    ['Signed customer contracts', 'None in the Company\'s name. Premium Offering subscriptions, where offered, are month-to-month consumer subscriptions subject to churn; no long-term committed revenue.', 'Binding contracts may support value if assignable and collectible.'],
    ['Outside financing', 'None. The Company had not completed or received any outside equity, debt or institutional financing and had no binding financing commitment as of the Valuation Date other than JGN\'s funding commitment under the JGN Agreement, which is terminable by JGN on notice.', 'Financing may affect valuation if closed or binding.'],
    ['Third-party equity offers', 'None. The Company had received no bona fide third-party offer to purchase Company equity, acquire the Company or establish an independent valuation as of the Valuation Date.', 'Bona fide offers may be valuation evidence.'],
    ['Marketability and transfer restrictions', 'Units are illiquid and subject to transfer restrictions, vesting and repurchase rights.', 'Illiquidity and restrictions affect value.'],
    ['Regulatory and execution risk', 'The Premium Offering sells sports betting picks and analysis, an activity that is regulated or restricted in some states and on some platforms (advertising, age and jurisdiction limits, affiliate and tout rules). The Company remained subject to substantial early-stage execution and commercialization risks, including completion and testing of the Platform; licensed data for production; app-store approval; cybersecurity, privacy and data-protection compliance; migration and control of repositories, domains, infrastructure and Company Accounts; completion and enforceability of IP assignments and the Brand License; dependence on JGN for the brand, the audience and funding; dependence on the Class B Member as the public face of the brand; subscriber acquisition and churn; competition from established picks services and sports apps; pricing uncertainty; reliance on third-party data, hosting, payment and community providers; and limited operating capital.', 'Early-stage execution and regulatory risk reduce certainty of future value.'],
    ['Dependence on Founders, JGN and talent', 'Company value materially depends on Founder execution, continued service and IP cooperation, on JGN\'s Brand License, promotion covenant and funding, and on the Class B Member\'s continued services.', 'Dependence increases risk.'],
    ['Market for Units', 'No public or private trading market for the Units is known.', 'Lack of marketability affects value.'],
    ['Contradictory facts', 'No undisclosed contradictory facts are known after reasonable review of the Company\'s records as of the Valuation Date. The Members specifically considered: the built but launch-stage Platform; the Company\'s lack of a bank account and of revenue in its own name; the JGN Funding Advances; the licensed rather than owned brand and audience; the Talent Agreement obligations; and the regulatory character of paid picks. The Members considered those facts together and concluded in good faith that they did not render the ' + money(FMV_TOTAL) + ' total equity Fair Market Value unsupported. If any material revenue, signed contract, financing, acquisition proposal, third-party equity offer, material asset, liability or other valuation-relevant fact existed as of the Valuation Date but was not disclosed in this memorandum, the valuation must be reconsidered before the Units are issued on the Actual Closing Date.', 'Contradictory facts must be resolved before the Units are issued on the Actual Closing Date.'],
  ], 'w3') +
  `<h2>3. GOOD-FAITH VALUATION FACTORS</h2>
<p>The ${money(FMV_TOTAL)} total company equity Fair Market Value reflects the Company's actual condition on the Valuation Date, including a built but launch-stage Platform; no cash other than the Founders' purchase price payments; no revenue in the Company's name; a brand and audience that the Company licenses and borrows rather than owns; JGN Funding Advances outstanding; no outside financing; no bona fide third-party equity or acquisition offers; no proven commercial adoption; no established product-market fit; limited operating history; material Founder, JGN and talent dependence; unresolved regulatory, commercialization and execution risk; restricted and illiquid Units; vesting and Company repurchase rights; and the need to complete Company Account migration.</p>
<p>The Members considered the totality of the Company's qualitative and quantitative valuation factors and exercised good-faith business judgment. No single valuation factor controlled the determination.</p>
<p>The Members considered the Platform to have value, but highly uncertain and risk-adjusted value, because, as of the Valuation Date, it was in launch stage with no revenue in the Company's name, unproven at scale, not independently valued, dependent on JGN funding, and still subject to commercialization, technical, regulatory, execution, market-adoption, churn and account-migration risk.</p>
<ul>
<li>The Company is a launch-stage Delaware LLC with founder-owned restricted Class A Units and a single Class B profits interest.</li>
<li>The Units are illiquid, privately held and subject to transfer restrictions, vesting, repurchase rights and member-governance controls.</li>
<li>The Company depends materially on Founder service, Founder IP assignments, Company Account control, the JGN Agreement (Brand License, promotion covenant and funding) and the Talent Agreement.</li>
<li>The record book does not include audited financial statements, binding third-party valuations, closed institutional financing, committed recurring revenue or signed acquisition offers.</li>
<li>The Company may not rely on the ${money(FMV_TOTAL)} conclusion if actual Valuation Date facts contradict the completed worksheet.</li>
</ul>
<h2>4. CONCLUSION</h2>
<p>Based on the facts documented in this memorandum, the Members determine in good faith that the total company equity Fair Market Value as of the Valuation Date is ${money(FMV_TOTAL)}, resulting in a Fair Market Value of $0.001 per Class A Unit and a Threshold Amount of ${money(THRESHOLD)} for the Class B Units, which therefore have no liquidation value on the Valuation Date. The determination is approved solely for the initial Founder purchase closing and the Class B issuance and may not be used as a later financing, acquisition, repurchase, litigation, accounting or tax valuation; any such use requires a new determination as of that later date.</p>
<h2>5. MEMBER ACKNOWLEDGMENT</h2>` + memberSigs(() => 'Class A Member');
  return doc(3, 'FOUNDER EQUITY FAIR MARKET VALUE DETERMINATION MEMORANDUM', body);
}

// 04 Founder Purchase Price Payment Instructions
function doc04() {
  const per = FOUNDERS.map(f => `<h3>${f.name}</h3>` + kv([['Units purchased', num(f.units) + ' Class A Units'], ['Per-Unit Price', '$0.001'], ['Purchase Price', price(f)], ['Capital Contribution Amount', price(f)], ['Paid by', 'Cash payment into the Company bank account by ACH, wire, Zelle or another bank-recorded method'], ['Date payment received'], ['Bank record reference'], ['Receipt Number']], 'kv2')).join('');
  const body = `<p><strong>Effective date:</strong> these instructions are effective on approval of the Initial Member and Organizational Written Consent and govern how each Founder's purchase price is paid under Section 3.5 of the Operating Agreement. The per-Founder records below are completed when the Company confirms and records each payment. Under Section 2.8 of the Operating Agreement, the Actual Closing Date, the Transfer Date, the Valuation Date and the vesting commencement date are the same date unless the Operating Agreement is amended under Article 16 to provide otherwise. ${DEFINED}</p>
<p>Each Founder pays the purchase price in cash. No promissory notes, deferred-payment rights, credits for services or intellectual property, credits for expenses paid by any Person, or other payment mechanics are authorized. No Founder pays any part of the purchase price to JGN.</p>
<p>Accounting treatment: each Founder's payment is that Founder's initial Capital Contribution in exchange for the issuance of restricted Class A Units. The Class B Member pays nothing for the Class B Units, which are profits interests.</p>` +
  kv([['Method', 'Cash payment into the Company\'s business checking account opened under the Banking Resolution, by ACH transfer, wire transfer, Zelle or another method recorded on the Company\'s bank statement, with the Founder\'s name in the payment memo where the method allows'], ['Payment amount', `Equal to the Founder's purchase price: ${FOUNDERS.map(f => price(f) + ' for ' + nbName(f)).join('; ')}; ${money(A_TOTAL_PRICE)} in total`], ['Timing', 'On or before the Actual Closing Date, after the Founder signs the Operating Agreement and the Founder\'s Restricted Unit Purchase and Issuance Agreement'], ['Supporting records', 'The Company\'s bank statement and the transaction record for each payment, kept with the Founder Payment and Capital Contribution Ledger'], ['Confirmation', 'The Chief Technology Officer confirms each payment against the bank records, and the Chief Executive Officer confirms the Chief Technology Officer\'s own'], ['Receipt', 'The Company issues each Founder a receipt once that Founder\'s payment is recorded'], ['Accounting', 'Credited to the Founder\'s Capital Account as an initial Capital Contribution on the Actual Closing Date under Operating Agreement Section 10.2'], ['Finality', 'Once the Actual Closing Date occurs, a recorded payment may not be reduced, refunded, offset or recharacterized. If the payments lapse under Section 3.6 of the Operating Agreement, no Units are issued and each payment is refunded without interest within 10 days after the lapse.']]) +
  per + coSig();
  return doc(4, 'FOUNDER PURCHASE PRICE PAYMENT INSTRUCTIONS', body);
}

// 05 Aggregate Founder Purchase Closing Statement
function doc05() {
  const per = FOUNDERS.map(f => `<h3>${f.name}</h3>` + kv([['Units', num(f.units) + ' Class A Units'], ['Fully diluted ownership', fdPct(f.units)], ['Per-Unit Price', '$0.001'], ['Purchase Price', price(f)], ['Capital Contribution Amount', price(f)], ['Paid by', PAID_BY], ['Payment recorded'], ['Immediately Vested', num(vested(f))], ['Restricted Units', num(vested(f))], ['Issuance condition', 'Execution and recorded payment required']], 'kv2')).join('');
  const body = EFF + per +
  `<h3>Brock Smith (Class B)</h3>` + kv([['Units', num(CLASS_B) + ' Class B Units'], ['Fully diluted ownership', fdPct(CLASS_B)], ['Purchase Price', 'None; profits interest with a Threshold Amount of ' + money(THRESHOLD)], ['Capital Contribution Amount', 'None'], ['Vesting', 'Per Talent Agreement Section 5.4'], ['Issuance condition', 'Actual Closing Date; no signature required (Operating Agreement Section 3.7)']], 'kv2') +
  `<h3>Total – all Founders (Class A)</h3>` + kv([['Units', num(CLASS_A) + ' Class A Units'], ['Fully diluted ownership', fdPct(CLASS_A)], ['Per-Unit Price', '$0.001'], ['Aggregate Purchase Price', money(A_TOTAL_PRICE)], ['Aggregate Capital Contribution', money(A_TOTAL_PRICE)], ['Paid by', 'Cash payments into the Company bank account'], ['All payments recorded'], ['Immediately Vested', num(CLASS_A / 2)], ['Restricted Units', num(CLASS_A / 2)], ['Issuance condition', 'All Founder closings complete']], 'kv2') +
  tbl(['Reconciliation', 'Amount'], [['Aggregate Founder Capital Contributions', money(A_TOTAL_PRICE)], ['Aggregate Founder purchase prices', money(A_TOTAL_PRICE)], ['Aggregate capital credited to Members\' Capital Accounts', money(A_TOTAL_PRICE)], ['Outstanding Units after closing (Class A plus Class B)', num(OUTSTANDING)], ['Reserved Units (unissued)', num(RESERVE)]]) +
  `<p>Founder Capital Contributions equal Founder purchase prices and equal aggregate capital credited to Members' Capital Accounts. The Class B issuance adds no capital.</p>
<p>The Company shall not mark any issuance or transfer complete until the applicable Founder has executed required documents and the Company has recorded the applicable payment.</p>` + coSig();
  return doc(5, 'AGGREGATE FOUNDER PURCHASE CLOSING STATEMENT', body);
}

// 06 Founder Payment and Capital Contribution Ledger
function doc06() {
  const per = FOUNDERS.map(f => `<h3>${f.name}</h3>` + kv([['Units', num(f.units) + ' Class A Units'], ['Per-Unit Price', '$0.001'], ['Purchase Price', price(f)], ['Capital Contribution Amount', price(f)], ['Paid by', PAID_BY], ['Payment method'], ['Date payment received'], ['Bank record reference'], ['Receipt Number'], ['Capital Account Credit', price(f)]], 'kv2')).join('');
  const body = EFF + per +
  `<h3>Total – all Founders</h3>` + kv([['Units', num(CLASS_A) + ' Class A Units'], ['Per-Unit Price', '$0.001'], ['Aggregate Purchase Price', money(A_TOTAL_PRICE)], ['Aggregate Capital Contribution', money(A_TOTAL_PRICE)], ['Paid by', 'Cash payments into the Company bank account'], ['Date last payment received'], ['Receipt Number Range'], ['Aggregate Capital Account Credit', money(A_TOTAL_PRICE)]], 'kv2') +
  tbl(['Reconciliation', 'Amount'], [['Aggregate Founder Capital Contributions', money(A_TOTAL_PRICE)], ['Aggregate Founder purchase prices', money(A_TOTAL_PRICE)], ['Aggregate capital credited to Members\' Capital Accounts', money(A_TOTAL_PRICE)]]) +
  `<p>Each payment is cash received into the Company's bank account. The Class B Member, Brock Smith, makes no payment and has an opening Capital Account of zero. Final accounting entries and Capital Account credits are recorded in the Company's books and tied to the Company's bank records and the Founder Purchase Price Receipts.</p>` + coSig();
  return doc(6, 'FOUNDER PAYMENT AND CAPITAL CONTRIBUTION LEDGER', body);
}

// 07 Company Officer Certificate
function doc07() {
  const body = DEF_ONLY +
  `<p>This certificate is signed after all payments, signatures and record updates are complete. The undersigned officer certifies, as of the date signed below, that:</p>
<ul>
<li>the Company received and recorded each Founder's purchase price payment and initial Capital Contribution listed in the Aggregate Founder Purchase Closing Statement;</li>
<li>the Company issued ${num(CLASS_A)} Class A Units to the Founders listed on Schedule A of the Operating Agreement and ${num(CLASS_B)} Class B Units to Brock Smith under Section 3.7 of the Operating Agreement, and ${num(RESERVE)} Units remain unissued as Reserved Units;</li>
<li>the aggregate Founder Capital Contributions equal ${money(A_TOTAL_PRICE)}, the aggregate Founder purchase prices equal ${money(A_TOTAL_PRICE)}, and the aggregate capital credited to Members' Capital Accounts equals ${money(A_TOTAL_PRICE)};</li>
<li>each payment was confirmed against the Company's bank records, by the Chief Technology Officer for each Founder other than himself and by the undersigned Chief Executive Officer for the Chief Technology Officer;</li>
<li>no fact arising after the Members signed the Founder Equity Fair Market Value Determination Memorandum and on or before the Actual Closing Date contradicts it;</li>
<li>the Company's Official Unit Ledger, Capitalization Table, Founder Equity and Vesting Ledger, Founder Payment and Capital Contribution Ledger and Members' Capital Accounts have been updated;</li>
<li>the Company delivered to Brock Smith a copy of the Operating Agreement and the Class B Unit Issuance Record, or will do so within 10 days after the Actual Closing Date;</li>
<li>the Company retained signed copies of the Operating Agreement, the Initial Member and Organizational Written Consent, the five Restricted Unit Purchase and Issuance Agreements, the Founder PIIA, the JGN Agreement, the JGN Member Consent Approving Nosebleed Agreement, the Class B Unit Issuance Record and the Founder Purchase Price Receipts issued to each Founder, and a copy of the Talent Agreement.</li>
</ul>` +
  kv([['Actual Closing Date'], ['Last payment received'], ['Receipt Number Range'], ['Bank record reference'], ['Aggregate purchase price', money(A_TOTAL_PRICE)], ['Aggregate Capital Contributions', money(A_TOTAL_PRICE)], ['Aggregate capital credited to Members\' Capital Accounts', money(A_TOTAL_PRICE)], ['Founder Payment and Capital Contribution Ledger updated'], ['Official Unit Ledger updated'], ['Capitalization Table updated'], ['Founder Equity and Vesting Ledger updated'], ['Members\' Capital Accounts updated']]) +
  coSig() +
  `<div class="sig"><p class="who">Payments confirmed</p><p>${CO}</p><p>By: _________________________________________</p><p>Name: ${CTO.name}</p><p>Title: ${CTO.office}</p><p>I confirmed each Founder's purchase price payment, other than my own, against the Company's bank records.</p><p>Date signed: __________________________________</p></div>`;
  return doc(7, 'COMPANY OFFICER CERTIFICATE – FOUNDER EQUITY CLOSING', body, { coverTitle: 'COMPANY OFFICER CERTIFICATE&nbsp;– FOUNDER EQUITY CLOSING', h1: CO_UP + ' COMPANY OFFICER CERTIFICATE&nbsp;– FOUNDER EQUITY CLOSING' });
}

// 08 Officer Appointment Record
function doc08() {
  const body = DEF_ONLY +
  `<p>This officer record is adopted under Resolution 11 of the Initial Member and Organizational Written Consent, effective upon approval of that consent, and continues in effect under the Operating Agreement on and after the Actual Closing Date. Spending thresholds are measured per vendor, engagement or related series of payments in any rolling 12-month period, as Operating Agreement Section 4.3 provides. An expense to be funded by JGN also requires JGN's funding approval under the JGN Agreement.</p>` +
  tbl(['Officer', 'Title', 'Core ordinary-course lane'], FOUNDERS.map(f => [nbName(f), `${f.office} ("${f.short}")`, f.lane]), 'w') +
  `<p>Brock Smith, the Class B Member, holds no office and provides services as an independent contractor under the Talent Agreement.</p>` +
  tbl(['Authority area', 'Approved authority'], [
    ['CEO and CTO ordinary-course spending', 'Up to $25,000 individually without separate Member approval.'],
    ['CEO and CTO spending over $25,000 and up to $50,000', 'Requires approval from at least one additional Founder then in Continuous Service.'],
    ['CEO and CTO spending over $50,000 and up to $100,000', 'Requires approval from at least two additional Founders then in Continuous Service.'],
    ['Other officer ordinary-course spending', 'Up to $5,000 within the officer\'s lane.'],
    ['Other officer spending over $5,000 and up to $100,000', 'Requires approval from at least two additional Founders then in Continuous Service.'],
    ['Any spending above $100,000', 'Requires Supermajority Approval in every case.'],
    ['Major Decisions', 'Must be approved under the Operating Agreement and cannot be taken by officer action alone.'],
    ['JGN Agreement enforcement', 'The Company acts through the Chief Technology Officer, or another officer who is not a member of JGN, in enforcing the JGN Agreement (Operating Agreement Section 8.2).'],
  ]) + coSig();
  return doc(8, 'OFFICER APPOINTMENT RECORD AND AUTHORITY CERTIFICATE', body);
}

// 09 Banking Resolution
function doc09() {
  const body = DEF_ONLY +
  `<p>The following banking resolution was approved by the Members under Resolution 11 of the Initial Member and Organizational Written Consent, effective upon approval of that consent, and continues in effect under the Operating Agreement on and after the Actual Closing Date.</p>
<p>1. Opening of Bank Account. The Company has no bank account as of the date of this resolution. The Authorized Banking Officers are authorized and directed to open, before the Actual Closing Date, a business checking account in the Company's legal name, ${CO}, under EIN ${EIN}, at a federally insured United States financial institution of their choosing, and may open additional treasury, savings, card, merchant, payment-processor and related financial accounts in the Company's legal name. The institution and the last four digits of each account number are recorded in the Company Account Schedule when the account is opened; no full account number appears in the record book.</p>
<p>2. Authorized Banking Officers. ${CEO.name}, as Chief Executive Officer, and ${CTO.name}, as Chief Technology Officer (each, an "Authorized Banking Officer"), are authorized to work with financial institutions and payment processors to open, maintain, access and administer Company accounts, subject to the Operating Agreement. Either Authorized Banking Officer may sign for the Company within the spending authority in Operating Agreement Section 4.3.</p>
<p>3. Founder Purchase Price Payments. Founder purchase prices are paid in cash into the Company's business checking account under Section 3.5 of the Operating Agreement. Those payments are confirmed against the Company's bank records as Section 3.5 of the Operating Agreement provides (the Chief Technology Officer for each payment, the Chief Executive Officer for the Chief Technology Officer's own), and the Authorized Banking Officers shall preserve those records.</p>
<p>4. JGN Funding Advances and Platform Revenue. Amounts JGN advances to the Company under the JGN Agreement after the account is opened are deposited into the Company's account and recorded in the JGN Funding Ledger. Subscription, membership and other Platform revenue is collected into Company accounts, or into JGN-held accounts for the Company's benefit pending transition, as the JGN Agreement provides.</p>
<p>5. No Expansion of Spending Authority. This resolution does not override, waive or expand the spending thresholds, budget rules, Major Decision approvals, related-party controls, debt approvals or Supermajority Approval requirements in the Operating Agreement.</p>
<p>6. Access Controls. Company financial accounts shall use Company-controlled email, MFA, password-manager controls, at least two Company-approved administrators where practical and record retention sufficient for tax, audit, diligence and acquisition review.</p>` + coSig();
  return doc(9, 'BANKING RESOLUTION', body);
}

// 10 Official Unit Ledger
function doc10() {
  const per = FOUNDERS.map(f => `<h3>${f.id} — ${f.name}</h3>` + kv([['Entry ID', f.id], ['Issuance date', 'Actual Closing Date'], ['Class', 'Class A Units'], ['Units', num(f.units)], ['Percentage Interest', outPct(f.units)], ['Voting Interest', votePct(f.units)], ['Fully Diluted Percentage', fdPct(f.units)], ['Per-Unit Price', '$0.001'], ['Total Purchase Price', price(f)], ['Purchase Price Paid By', PAID_BY], ['Vesting Status', '50% vested; 50% restricted'], ['Original Cost', '$0.001 per Unit'], ['Certificate Status', 'Uncertificated book-entry interest']], 'kv2')).join('');
  const brock = `<h3>${BROCK.id} — ${BROCK.name}</h3>` + kv([['Entry ID', BROCK.id], ['Issuance date', 'Actual Closing Date'], ['Class', 'Class B Units (non-voting; profits interest)'], ['Units', num(BROCK.units)], ['Percentage Interest', outPct(BROCK.units)], ['Voting Interest', 'None'], ['Fully Diluted Percentage', fdPct(BROCK.units)], ['Threshold Amount', money(THRESHOLD)], ['Purchase Price', 'None'], ['Issued under', 'Operating Agreement Section 3.7; Talent Agreement Section 5.1 (Initial Units)'], ['Vesting Status', 'Forfeitable until vested under Talent Agreement Section 5.4'], ['Original Cost', 'Zero'], ['Certificate Status', 'Uncertificated book-entry interest; holder admitted without signature']], 'kv2');
  const reserve = `<h3>Reserved Units</h3>` + kv([['Status', 'Authorized and unissued'], ['Units', num(RESERVE)], ['Fully Diluted Percentage', fdPct(RESERVE)], ['Purpose', 'Future strategic partners (Operating Agreement Section 3.13) and Milestone Units under the Talent Agreement (Operating Agreement Section 3.7)'], ['Issuance', 'Strategic-partner issuances require Supermajority Approval as a Major Decision; Milestone Units are issued when earned'], ['Rights', 'None until issued; not counted in any threshold']], 'kv2');
  const body = EFF + per + brock + reserve +
  tbl(['Summary', 'Units'], [['Class A Units issued', num(CLASS_A)], ['Class B Units issued', num(CLASS_B)], ['Outstanding Units', num(OUTSTANDING)], ['Reserved Units (unissued)', num(RESERVE)], ['Authorized Units', num(AUTH_UNITS)]]) +
  `<p class="note">Ledger note: all issued Class A Units vote and participate in distributions and tax allocations whether vested or unvested, subject to Operating Agreement Section 7.5 in a Change of Control. Vesting affects only the Company's contractual repurchase right, related recordkeeping and the timing of, and entitlement to, consideration under Section 7.5 of the Operating Agreement. Class B Units do not vote and share in distributions only above the Threshold Amount (Operating Agreement Section 10.5).</p>` + coSig();
  return doc(10, 'OFFICIAL UNIT LEDGER', body);
}

// 11 Capitalization Table
function doc11() {
  const rows = FOUNDERS.map(f => [nbName(f), f.office, 'A', num(f.units), outPct(f.units), votePct(f.units), fdPct(f.units)]);
  rows.push([nbName(BROCK), 'Co-Founder', 'B', num(BROCK.units), outPct(BROCK.units), 'None', fdPct(BROCK.units)]);
  rows.push(['Reserved Units', 'Unissued', '', num(RESERVE), 'Not outstanding', 'Not outstanding', fdPct(RESERVE)]);
  rows.push(['<strong>Total</strong>', '', '', '<strong>' + num(AUTH_UNITS) + '</strong>', '<strong>100%</strong>', '<strong>100%</strong>', '<strong>100%</strong>']);
  const rows2 = FOUNDERS.map(f => [nbName(f), num(f.units), '$0.001', price(f), num(vested(f)), num(vested(f)), 'Cash']);
  rows2.push([nbName(BROCK), num(BROCK.units), 'None', 'None', 'Per Talent Agreement Section 5.4', 'Per Talent Agreement Section 5.4', 'Profits interest; no payment']);
  rows2.push(['<strong>Total issued</strong>', '<strong>' + num(OUTSTANDING) + '</strong>', '', '<strong>' + money(A_TOTAL_PRICE) + '</strong>', '<strong>' + num(CLASS_A / 2) + '</strong>', '<strong>' + num(CLASS_A / 2) + '</strong>', '']);
  const body = DEF_ONLY +
  `<p>Fully diluted capitalization treats the ${num(RESERVE)} Reserved Units as issued. No options, warrants or convertible securities exist. The only equity commitment other than the issued Units is the Milestone Units under the Talent Agreement, which, if earned, are issued from the Reserved Units up to a cumulative 5% fully diluted interest for Brock Smith (including his Class B Units).</p>` +
  tbl(['Member', 'Title', 'Class', 'Units', 'Outstanding % (of ' + num(OUTSTANDING) + ')', 'Voting % (of ' + num(CLASS_A) + ' Class A)', 'Fully diluted % (of ' + num(AUTH_UNITS) + ')'], rows) +
  tbl(['Member', 'Units', 'Per-Unit price', 'Purchase price / Capital Contribution', 'Immediately vested', 'Unvested', 'Paid by'], rows2) +
  kv([['Total company equity FMV as of Transfer Date', money(FMV_TOTAL)], ['FMV per Class A Unit', '$0.001'], ['Class B Threshold Amount', money(THRESHOLD)], ['Equity incentive pool', 'None; the Reserved Units are reserved for strategic partners and Milestone Units'], ['Interest types', 'Class A: restricted Common Units constituting capital interests. Class B: non-voting profits interests.'], ['Not a future valuation', `The ${money(FMV_TOTAL)} figure is the total equity FMV for the Founder issuance date only, not a financing, enterprise-value or acquisition valuation.`]]) + coSig();
  return doc(11, 'CAPITALIZATION TABLE', body);
}

// 12 Founder Equity and Vesting Ledger
function doc12() {
  const per = FOUNDERS.map(f => `<h3>${f.name}</h3>` + kv([['Issued Units', num(f.units) + ' Class A Units'], ['Purchase Price', price(f)], ['Original Cost', '$0.001 per Unit'], ['Immediately Vested Units', num(vested(f))], ['Restricted Units', num(vested(f))], ['Monthly Vesting Amount', `${num(monthly(f))} Units per month (${num(vested(f))} divided by 48, rounded down), final installment trued up under Operating Agreement Section 6.2`]], 'kv2')).join('');
  const body = DEF_ONLY +
  `<p>The vesting commencement date is the Actual Closing Date. 50% of each Founder's issued Class A Units vest immediately. The remaining 50% vest in 48 equal monthly installments, subject to Continuous Service and the Operating Agreement.</p>` + per +
  `<h3>Brock Smith (Class B)</h3>` + kv([['Issued Units', num(CLASS_B) + ' Class B Units'], ['Purchase Price', 'None'], ['Original Cost', 'Zero'], ['Vesting', 'The Class B Units vest on the earlier of the $25,000 Cumulative Qualifying Revenue Milestone and twelve consecutive months of performance without an uncured Shortfall Notice or Value Notice, and are forfeited before vesting only in the cases Talent Agreement Section 5.4 states; Operating Agreement Section 6.16 applies.'], ['Change of Control', 'Per Talent Agreement Section 5.9.']], 'kv2') +
  `<p class="note">Rounding note: monthly installments are rounded down to whole Units as shown above, and the rounding difference vests in the final (48th) installment under Operating Agreement Section 6.2.</p>
<p class="note">Departure note: unvested Class A Units remain subject to automatic repurchase at the lower of Original Cost and Fair Market Value unless a higher price is required by signed agreement or law. Vested Units are not subject to repurchase at Original Cost; they remain subject to the Fair Market Value call options under Operating Agreement Sections 6.8 (Bad Leaver), 6.13 (voluntary departure other than as a Good Leaver, or termination for Cause) and 6.15 (competition), transfer restrictions and the other rights expressly set forth in the Operating Agreement. Monthly vesting is suspended during an uncured default under Operating Agreement Section 6.14, with the schedule extended by the suspended months.</p>` + coSig();
  return doc(12, 'FOUNDER EQUITY AND VESTING LEDGER', body);
}

// 13 Founder Contribution and Separation Schedule
function doc13() {
  const built = { 'Nicholas Restivo': 'Began building the app, the website and the Discord community before the Actual Closing Date.', 'Christian Clark': 'Brought in to complete the app, the website and the Discord community for launch; not a member of JGN.', 'Stephen Bickel': 'Refined the website before the Actual Closing Date.', 'Gabriel DiDario': 'No specific pre-closing Platform development is recorded for this Founder.', 'Michael Del Bene': 'No specific pre-closing Platform development is recorded for this Founder.' };
  const per = FOUNDERS.map(f => `<h3>${f.name}</h3>` + kv([
    ['Purchase Price / initial Capital Contribution', `${price(f)}, paid in cash into the Company bank account under Operating Agreement Section 3.5`],
    ['Separate IP and Founder obligations', 'Founder PIIA, IP assignment, confidentiality, invention assignment, data-security, Founder duties and restrictive-covenant obligations remain separately enforceable.'],
    ['Pre-closing services', built[f.name] + ' Any services performed for the Platform before the Actual Closing Date are not consideration for Units and create no claim for compensation, reimbursement or additional Units (Operating Agreement Section 3.8); the resulting work product is assigned under the Founder PIIA and, to the extent JGN owned or controlled it, the JGN Agreement.'],
    ['Founder Advances / reimbursable expenses', 'None. No historical Company operating expense was paid by this Founder personally; every such expense was funded by JGN as a JGN Funding Advance and is recorded in the Historical Company Operating Expense and JGN Funding Advance Schedule.'],
    ['JGN interest', f.jgn ? 'Member of JGN Media LLC (25%), disclosed under Schedule D of the Operating Agreement. JGN Funding Advances are owed to JGN by the Company only as the JGN Agreement provides and give this Founder no personal claim against the Company or any Member.' : 'None. Not a member of JGN Media LLC.'],
    ['Other contributions', 'Any future non-equity contribution, advance, reimbursement, loan or capital call must be separately documented and approved if material.'],
  ], 'kv2')).join('');
  const body = DEF_ONLY +
  `<p>This schedule distinguishes among the cash purchase prices that pay for Class A Units, the Class B profits interest, separate IP and Founder obligations, pre-closing services, JGN Funding Advances and other Company contributions.</p>` + per +
  `<h3>Brock Smith (Class B Member)</h3>` + kv([
    ['Class B Units', `${num(CLASS_B)} Class B Units issued under Operating Agreement Section 3.7 as the Initial Units under Talent Agreement Section 5.1, as profits interests with a Threshold Amount of ${money(THRESHOLD)}; no purchase price; no Capital Contribution.`],
    ['Services', 'Handicapping, content, live-session, community and brand-representation services under the Talent Agreement, compensated by the Monthly Fee, bonuses, revenue shares and the equity in Section 5 of the Talent Agreement. The Class B Units are issued in performance of that agreement and in recognition of his co-founder role in the Platform\'s content and community.'],
    ['IP', 'Work Product relating to the Platform and the Premium Offering is assigned to the Company, and Work Product relating to the Brand and the Managed Accounts to JGN, under Talent Agreement Section 8.1.'],
    ['Milestone Units', 'Issued from the Reserved Units when earned under Talent Agreement Section 5.2, up to a cumulative 5% fully diluted interest.'],
    ['Other', 'No other equity, contribution, advance or claim.'],
  ], 'kv2') +
  `<p>Other than the cash purchase price, no Founder duty, IP assignment, pre-closing service, Founder Advance, reimbursement claim, vendor charge, Company expense or JGN expense substitutes for any Founder's purchase price or initial Capital Contribution. Future Founder funding of Company expenses must be separately documented as a future capital call, capital contribution agreement, loan or Founder Advance, and JGN funding is governed by the JGN Agreement.</p>` + coSig();
  return doc(13, 'FOUNDER CONTRIBUTION AND SEPARATION SCHEDULE', body);
}

module.exports = { doc00, doc02, doc03, doc04, doc05, doc06, doc07, doc08, doc09, doc10, doc11, doc12, doc13 };
